function attachTreeListeners(){document.querySelectorAll('.tree-item-content').forEach(el=>{el.addEventListener('click',handleTreeClick);el.addEventListener('contextmenu',handleTreeContextMenu)});document.querySelectorAll('[data-drop-target="true"]').forEach(el=>{el.addEventListener('dragover',handleDragOver);el.addEventListener('dragenter',handleDragEnter);el.addEventListener('dragleave',handleDragLeave);el.addEventListener('drop',handleDrop)})}async function handleTreeClick(e){const el=e.currentTarget;const p=el.dataset.path;const hc=el.dataset.hasChildren==='true';if(hc){if(state.expandedPaths.has(p))state.expandedPaths.delete(p);else{state.expandedPaths.add(p);if(!state.treeData[p])await loadTree(p)}}navigateTo(p,true)}
function isExternalFileDrag(e){return!state.draggedPath&&e.dataTransfer&&e.dataTransfer.types&&Array.from(e.dataTransfer.types).includes('Files')}
function handleDragStart(e){const p=e.currentTarget.dataset.path;state.draggedPath=p;if(mouseDownSelectedPaths&&mouseDownSelectedPaths.length>1){state.draggedPaths=mouseDownSelectedPaths}else{state.draggedPaths=null}e.currentTarget.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',p)}function handleDragEnd(e){e.currentTarget.classList.remove('dragging');state.draggedPath=null;state.draggedPaths=null;document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'))}function handleDragOver(e){if(isExternalFileDrag(e)){e.preventDefault();e.dataTransfer.dropEffect='copy';return}e.preventDefault();e.stopPropagation();const paths=state.draggedPaths||[state.draggedPath];const d=e.currentTarget.dataset.path||'';if(!paths.length||paths.includes(d))return;e.dataTransfer.dropEffect='move'}function handleDragEnter(e){if(isExternalFileDrag(e)){e.preventDefault();return}e.preventDefault();const paths=state.draggedPaths||[state.draggedPath];const d=e.currentTarget.dataset.path||'';if(!paths.length||paths.includes(d))return;e.currentTarget.classList.add('drag-over')}function handleDragLeave(e){if(!isExternalFileDrag(e))e.currentTarget.classList.remove('drag-over')}async function handleDrop(e){if(isExternalFileDrag(e))return;e.preventDefault();e.stopPropagation();e.currentTarget.classList.remove('drag-over');const d=e.currentTarget.dataset.path||'';const paths=state.draggedPaths||[state.draggedPath];state.draggedPath=null;state.draggedPaths=null;if(!paths||!paths.length)return;await moveItems(paths,d)}
function navigateTo(path,skip){state.currentPath=path;state.selectedItem=null;state.selectedItems.clear();elements.currentPathInput.value=ROOT_PREFIX+(path?'/'+path:'')+'/';showStatus('読み込み中...');api(`/browse?path=${encodeURIComponent(path)}`).then(d=>{state.items=d.items;renderFileList();updateItemCount();showStatus('準備完了')}).catch(e=>showStatus(`エラー: ${e.message}`));if(!skip)expandParentPaths(path);renderTree()}
